import json,os,subprocess,time,configparser
from pathlib import Path
assert Path('/sys/class/dmi/id/product_name').read_text().strip()=='MTTKDE release capture'
home=Path.home()
def run(*args):subprocess.run(args,check=True,stdout=subprocess.DEVNULL)
def snapshot():
 p=configparser.ConfigParser();p.optionxform=str;p.read(home/'.config/kwinrc')
 return dict(p['Effect-liquidglass'])
def wait(mode):
 for _ in range(160):
  state=json.loads((home/'.local/state/mac-tahoe-liquid-kde/appearance.json').read_text())
  if state.get('applied')==mode and not state.get('pending'):return state
  time.sleep(.25)
 raise AssertionError(state)
settings={'BlurStrength':'6.25','RefractionWidth':'13.5','GradientTopOpacity':'0.73','PopupCornerRadius':'11.75'}
original=snapshot()
for key,value in settings.items():run('kwriteconfig6','--file','kwinrc','--group','Effect-liquidglass','--key',key,value)
expected=snapshot()
pids=[]
for name in ('appearance-probe','appearance-plasmoids'):
 for record in json.loads((home/name/'processes.json').read_text()):
  p=Path('/proc')/str(record['pid'])/'stat';pids.append((str(p),p.read_text().split(') ',1)[1].split()[19]))
run('kwriteconfig6','--file','kdeglobals','--group','KDE','--key','AutomaticLookAndFeel','true')
results=[]
for mode in ('light','dark'):
 run('plasma-apply-colorscheme','MacTahoeLiquidKde'+mode.title())
 state=wait(mode)
 assert state['preference']=='native-auto',state
 assert snapshot()==expected
 for name,identity in pids:assert Path(name).read_text().split(') ',1)[1].split()[19]==identity
 results.append({'mode':mode,'state':state,'optics':snapshot(),'processes':pids})
(home/'appearance-preservation.json').write_text(json.dumps(results,indent=2))
for key in settings:
 if key in original:run('kwriteconfig6','--file','kwinrc','--group','Effect-liquidglass','--key',key,original[key])
 else:run('kwriteconfig6','--file','kwinrc','--group','Effect-liquidglass','--key',key,'--delete')
run('qdbus6','org.kde.KWin','/KWin','org.kde.KWin.reconfigure')
print('native auto, saved optics and persistent application identities passed')
